      "legal": {
        "title": "Informacje prawne",
        "backToHome": "Powrót do strony głównej",
        "privacy": {
          "title": "Polityka prywatności",
          "lastUpdated": "Ostatnia aktualizacja",
          "section1": {
            "title": "Postanowienia ogólne",
            "content": "Niniejsza Polityka prywatności opisuje, w jaki sposób MUZIKA Distribution gromadzi, wykorzystuje i chroni Twoje dane osobowe podczas korzystania z naszych usług."
          },
          "section2": {
            "title": "Zbierane informacje",
            "content": "Zbieramy następujące rodzaje informacji:",
            "item1": "Dane identyfikacyjne (imię, e-mail, numer telefonu)",
            "item2": "Informacje płatnicze i rozliczeniowe",
            "item3": "Treści muzyczne i metadane",
            "item4": "Dane o użytkowaniu i analizy"
          },
          "section3": {
            "title": "Wykorzystanie informacji",
            "content": "Twoje informacje wykorzystujemy w następujących celach:",
            "item1": "Świadczenie i ulepszanie naszych usług",
            "item2": "Przetwarzanie płatności i tantiem",
            "item3": "Komunikacja z Tobą w sprawie Twojego konta",
            "item4": "Przestrzeganie obowiązków prawnych"
          },
          "section4": {
            "title": "Ochrona danych",
            "content": "Wdrażamy odpowiednie środki techniczne i organizacyjne w celu ochrony Twoich danych osobowych przed nieuprawnionym dostępem, zmianą, ujawnieniem lub zniszczeniem."
          },
          "section5": {
            "title": "Twoje prawa",
            "content": "Masz prawo do dostępu, poprawiania, usuwania lub ograniczenia przetwarzania Twoich danych osobowych. Skontaktuj się z nami pod adresem support@muzika.ua, aby skorzystać z tych praw."
          },
          "section6": {
            "title": "Kontakt",
            "content": "W przypadku pytań dotyczących niniejszej Polityki prywatności prosimy o kontakt: support@muzika.ua"
          }
        },
        "offer": {
          "title": "Umowa oferty publicznej",
          "lastUpdated": "Ostatnia aktualizacja",
          "section1": {
            "title": "Przedmiot umowy",
            "content": "Niniejsza umowa reguluje warunki świadczenia usług dystrybucji muzyki przez MUZIKA Distribution dla artystów i wytwórni."
          },
          "section2": {
            "title": "Opis usług",
            "content": "MUZIKA Distribution świadczy usługi cyfrowej dystrybucji muzyki na główne platformy streamingowe na całym świecie."
          },
          "section3": {
            "title": "Prawa i obowiązki",
            "content": "Artysta udziela MUZIKA niewyłącznych praw do dystrybucji treści muzycznych na platformach cyfrowych. MUZIKA zapewnia prawidłowe naliczanie i wypłatę tantiem."
          },
          "section4": {
            "title": "Warunki płatności",
            "content": "Opłaty za dystrybucję są płatne z góry za każde wydanie. Tantiemy są wypłacane kwartalnie, z minimalnym progiem 50 USD."
          },
          "section5": {
            "title": "Okres obowiązywania i rozwiązanie",
            "content": "Niniejsza umowa wchodzi w życie z chwilą akceptacji i obowiązuje do jej rozwiązania. Każda ze stron może ją rozwiązać z 30-dniowym wyprzedzeniem na piśmie."
          },
          "section6": {
            "title": "Odpowiedzialność",
            "content": "MUZIKA nie ponosi odpowiedzialności za decyzje platform streamingowych dotyczące usuwania treści lub umieszczania na playlistach."
          },
          "section7": {
            "title": "Prawo właściwe",
            "content": "Niniejsza umowa podlega prawu Ukrainy. Spory będą rozstrzygane w drodze negocjacji lub postępowania sądowego w Kijowie na Ukrainie."
          }
        },
        "terms": {
          "title": "Regulamin",
          "intro": "Niniejszy Regulamin reguluje korzystanie z platformy MUZIKA UA, należącej do FOP Striletskyy Pavlo Ihorovych, znajdującej się pod adresami https://muzika.ua i https://muzika-dist.com. Korzystając ze stron Platformy, akceptujesz niniejszy Regulamin.",
          "section1": {
            "title": "Postanowienia ogólne",
            "item1": "Platforma świadczy usługi cyfrowej dystrybucji muzyki, dostępu do konta osobistego oraz sprzedaży powiązanych produktów cyfrowych.",
            "item2": "Usługi są dostępne dla osób fizycznych i firm, które akceptują warunki niniejszej umowy.",
            "item3": "Wszystkie płatności są dokonywane w walucie narodowej Ukrainy — hrywnie (UAH)."
          },
          "section2": {
            "title": "Procedura świadczenia usług",
            "item1": "Użytkownik wypełnia formularz rejestracyjny w celu utworzenia konta osobistego na muzika-dist.com.",
            "item2": "Po potwierdzeniu rejestracji Użytkownik uzyskuje dostęp do funkcjonalności przesyłania wydań, zarządzania dystrybucją i zamawiania usług.",
            "item3": "Usługa jest świadczona po otrzymaniu płatności zgodnie z jej opisem."
          },
          "section3": {
            "title": "Termin realizacji usług",
            "item1": "Dostęp do produktów cyfrowych jest nieograniczony (o ile nie określono inaczej).",
            "item2": "Usługi dystrybucji są świadczone w ciągu 3-5 dni roboczych po dokonaniu płatności i przekazaniu kompletnych materiałów.",
            "item3": "W przypadku opóźnienia lub siły wyższej informujemy klienta drogą e-mailową."
          },
          "section4": {
            "title": "Obszar świadczenia usług",
            "item1": "Usługi są świadczone użytkownikom z dowolnego kraju na świecie.",
            "item2": "Wszystkie transakcje są przeprowadzane online. Fizyczna dostawa towarów nie jest przewidziana."
          },
          "section5": {
            "title": "Metody płatności",
            "item1": "Płatność jest możliwa przez serwis WayForPay za pomocą Visa/MasterCard, Apple Pay, Google Pay i innych dostępnych metod.",
            "item2": "Po potwierdzeniu płatności użytkownik otrzyma e-mail z potwierdzeniem.",
            "item3": "Wszystkie płatności są chronione zgodnie ze standardami WayForPay."
          },
          "section6": {
            "title": "Zwroty",
            "item1": "Zwroty są możliwe, jeśli usługa nie została świadczona z przyczyn technicznych po stronie Platformy.",
            "item2": "Wnioski o zwrot należy wysłać na muzika.ua.info@gmail.com w ciągu 7 dni od dokonania płatności.",
            "item3": "Środki są zwracane w ciągu 14 dni kalendarzowych po potwierdzeniu wniosku."
          },
          "section7": {
            "title": "Kontakt",
            "content": "FOP Striletskyy Pavlo Ihorovych"
          }
        },
        "refund": {
          "title": "Polityka zwrotów",
          "lastUpdated": "Ostatnia aktualizacja",
          "section1": {
            "title": "Zasady ogólne",
            "content": "MUZIKA Distribution przetwarza zwroty zgodnie z ukraińskim prawem ochrony konsumentów oraz naszymi umowami o świadczenie usług."
          },
          "section2": {
            "title": "Kwalifikujące się zwroty",
            "content": "Zwroty mogą być dokonane w następujących przypadkach:",
            "item1": "Błędy techniczne uniemożliwiające świadczenie usługi",
            "item2": "Zduplikowane płatności",
            "item3": "Anulowanie usługi przed rozpoczęciem dystrybucji"
          },
          "section3": {
            "title": "Usługi bezzwrotne",
            "content": "Po dostarczeniu treści na platformy streamingowe opłaty za dystrybucję nie podlegają zwrotowi, ponieważ usługa została już wykonana."
          },
          "section4": {
            "title": "Proces zwrotu",
            "content": "Aby złożyć wniosek o zwrot, skontaktuj się z support@muzika.ua, podając szczegóły zamówienia. Zwroty są przetwarzane w ciągu 5-10 dni roboczych na oryginalną metodę płatności."
          },
          "section5": {
            "title": "Kontakt",
            "content": "W sprawie zwrotów: support@muzika.ua"
          }
        }
      },
